using System.Data;using Backend.BDFolder;using Backend.Exceptions;using Backend.Helpers;using Backend.Models;using Backend.Policies;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.Logging;using Polly;namespace Backend.Services;public class SucursalService{    private readonly IDbContextFactory<TransportesRojasDbContext> _factory;    private readonly ILogger<SucursalService> _logger;    private readonly ResiliencePipeline _pipeline;    public SucursalService(        IDbContextFactory<TransportesRojasDbContext> factory,        ILogger<SucursalService> logger)    {        _factory = factory;        _logger = logger;        _pipeline = PollyPolicies.CrearPipelineSerializacion(logger);    }    public async Task<List<SucursalResponse>> GetSucursalesAsync(int skip = 0, int take = 100)    {        await using var ctx = await _factory.CreateDbContextAsync();        return await ctx.Sucursales            .AsNoTracking()            .Include(s => s.Direccion)            .OrderBy(s => s.Id)            .Skip(skip)            .Take(take)            .Select(s => new SucursalResponse(                s.Id,                s.Nombre,                s.Direccion != null ? s.Direccion.Calle : null,                s.Direccion != null ? s.Direccion.Municipio : null,                s.Direccion != null ? s.Direccion.Estado : null,                s.Direccion != null ? s.Direccion.CodigoPostal : null,                s.Telefono))            .ToListAsync();    }    public async Task<SucursalResponse?> GetSucursalByIdAsync(long id)    {        await using var ctx = await _factory.CreateDbContextAsync();        var sucursal = await ctx.Sucursales            .AsNoTracking()            .Include(s => s.Direccion)            .FirstOrDefaultAsync(s => s.Id == id);        return sucursal is null            ? null            : new SucursalResponse(                sucursal.Id,                sucursal.Nombre,                sucursal.Direccion?.Calle,                sucursal.Direccion?.Municipio,                sucursal.Direccion?.Estado,                sucursal.Direccion?.CodigoPostal,                sucursal.Telefono);    }    public async Task<SucursalResponse> CreateSucursalAsync(CrearSucursalModel model)    {        return await _pipeline.ExecuteAsync(async ct =>        {            await using var ctx = await _factory.CreateDbContextAsync(ct);            await using var tx = await ctx.Database                .BeginTransactionAsync(IsolationLevel.Serializable, ct);            try            {                var existeNombre = await ctx.Sucursales                    .AnyAsync(s => s.Nombre == model.Nombre, ct);                if (existeNombre)                    throw new InvalidOperationException(                        $"Ya existe una sucursal con el nombre '{model.Nombre}'.");                var nueva = new Sucursal                {                    Nombre = model.Nombre,                    Telefono = model.Telefono,                    Direccion = new Direccion                    {                        Calle = model.Direccion,                        Municipio = model.Ciudad,                        Estado = model.Estado,                        CodigoPostal = model.CodigoPostal                    }                };                ctx.Sucursales.Add(nueva);                await ctx.SaveChangesAsync(ct);                await tx.CommitAsync(ct);                _logger.LogInformation("Sucursal creada. Id={Id}, Nombre='{Nombre}'",                    nueva.Id, nueva.Nombre);                return new SucursalResponse(                    nueva.Id,                    nueva.Nombre,                    nueva.Direccion.Calle,                    nueva.Direccion.Municipio,                    nueva.Direccion.Estado,                    nueva.Direccion.CodigoPostal,                    nueva.Telefono);            }            catch (Exception ex) when (PostgresErrorHelper.IsSerializationFailure(ex))            {                await RollbackSafeAsync(tx);                throw new RetryableException("Conflicto de serialización al crear sucursal.", ex);            }            catch (InvalidOperationException)            {                await RollbackSafeAsync(tx);                throw;            }            catch (Exception)            {                await RollbackSafeAsync(tx);                throw;            }        }, CancellationToken.None);    }    public async Task<bool> UpdateSucursalAsync(long id, ActualizarSucursalModel model)    {        return await _pipeline.ExecuteAsync(async ct =>        {            await using var ctx = await _factory.CreateDbContextAsync(ct);            await using var tx = await ctx.Database                .BeginTransactionAsync(IsolationLevel.Serializable, ct);            try            {                var sucursal = await ctx.Sucursales                    .Include(s => s.Direccion)                    .FirstOrDefaultAsync(s => s.Id == id, ct);                if (sucursal is null) return false;                var existeNombre = await ctx.Sucursales                    .AnyAsync(s => s.Nombre == model.Nombre && s.Id != id, ct);                if (existeNombre)                    throw new InvalidOperationException(                        $"Ya existe otra sucursal con el nombre '{model.Nombre}'.");                sucursal.Nombre = model.Nombre;                sucursal.Telefono = model.Telefono;                if (sucursal.Direccion is null)                {                    sucursal.Direccion = new Direccion                    {                        Calle = model.Direccion,                        Municipio = model.Ciudad,                        Estado = model.Estado,                        CodigoPostal = model.CodigoPostal                    };                }                else                {                    sucursal.Direccion.Calle = model.Direccion;                    sucursal.Direccion.Municipio = model.Ciudad;                    sucursal.Direccion.Estado = model.Estado;                    sucursal.Direccion.CodigoPostal = model.CodigoPostal;                }                await ctx.SaveChangesAsync(ct);                await tx.CommitAsync(ct);                _logger.LogInformation("Sucursal actualizada. Id={Id}", id);                return true;            }            catch (Exception ex) when (PostgresErrorHelper.IsSerializationFailure(ex))            {                await RollbackSafeAsync(tx);                throw new RetryableException("Conflicto de serialización al actualizar sucursal.", ex);            }            catch (InvalidOperationException)            {                await RollbackSafeAsync(tx);                throw;            }            catch (Exception)            {                await RollbackSafeAsync(tx);                throw;            }        }, CancellationToken.None);    }    public async Task<bool> DeleteSucursalAsync(long id)    {        return await _pipeline.ExecuteAsync(async ct =>        {            await using var ctx = await _factory.CreateDbContextAsync(ct);            await using var tx = await ctx.Database                .BeginTransactionAsync(IsolationLevel.Serializable, ct);            try            {                var sucursal = await ctx.Sucursales                    .Include(s => s.Direccion)                    .FirstOrDefaultAsync(s => s.Id == id, ct);                if (sucursal is null) return false;                var tieneEmpleados = await ctx.Empleados                    .AnyAsync(e => e.SucursalId == id, ct);                if (tieneEmpleados)                    throw new InvalidOperationException(                        "No se puede eliminar la sucursal porque tiene empleados asignados.");                if (sucursal.Direccion is not null)                    ctx.Direcciones.Remove(sucursal.Direccion);                ctx.Sucursales.Remove(sucursal);                await ctx.SaveChangesAsync(ct);                await tx.CommitAsync(ct);                _logger.LogInformation("Sucursal eliminada. Id={Id}", id);                return true;            }            catch (Exception ex) when (PostgresErrorHelper.IsSerializationFailure(ex))            {                await RollbackSafeAsync(tx);                throw new RetryableException("Conflicto de serialización al eliminar sucursal.", ex);            }            catch (InvalidOperationException)            {                await RollbackSafeAsync(tx);                throw;            }            catch (Exception)            {                await RollbackSafeAsync(tx);                throw;            }        }, CancellationToken.None);    }    private async Task RollbackSafeAsync(        Microsoft.EntityFrameworkCore.Storage.IDbContextTransaction tx)    {        try { await tx.RollbackAsync(); }        catch (Exception rollbackEx)        {            _logger.LogWarning(rollbackEx, "Error durante rollback (puede ser esperado).");        }    }}